CREATE TABLE tenant.fin_settings(company_id uuid PRIMARY KEY REFERENCES platform.companies(id),base_currency text NOT NULL DEFAULT 'EGP' CHECK(base_currency='EGP'),fiscal_month integer NOT NULL DEFAULT 1 CHECK(fiscal_month BETWEEN 1 AND 12),vat_bps integer NOT NULL DEFAULT 0 CHECK(vat_bps BETWEEN 0 AND 10000),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenant.fin_counters(company_id uuid NOT NULL REFERENCES platform.companies(id),kind text NOT NULL,n bigint NOT NULL DEFAULT 0,PRIMARY KEY(company_id,kind));
CREATE TABLE tenant.fin_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES platform.companies(id),code text NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('asset','liability','equity','revenue','expense')),system_key text,active boolean NOT NULL DEFAULT true,is_cash boolean NOT NULL DEFAULT false,cash_flow text NOT NULL DEFAULT 'operating' CHECK(cash_flow IN ('operating','investing','financing')),version integer NOT NULL DEFAULT 1,UNIQUE(company_id,id),UNIQUE(company_id,code),UNIQUE(company_id,system_key));
CREATE TABLE tenant.fin_dimensions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES platform.companies(id),kind text NOT NULL CHECK(kind IN ('branch','cost_centre','project','team')),name text NOT NULL,active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,UNIQUE(company_id,id),UNIQUE(company_id,kind,name));
CREATE TABLE tenant.fin_parties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES platform.companies(id),kind text NOT NULL CHECK(kind IN ('customer','developer','supplier','employee')),name text NOT NULL,email text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',tax_number text NOT NULL DEFAULT '',reference_id uuid,active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,UNIQUE(company_id,id),UNIQUE(company_id,kind,reference_id));
CREATE TABLE tenant.fin_periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES platform.companies(id),name text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,closed boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,CHECK(end_date>=start_date),UNIQUE(company_id,id));
CREATE TABLE tenant.fin_journals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES platform.companies(id),code text NOT NULL,entry_date date NOT NULL,memo text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted')),source_kind text NOT NULL DEFAULT 'manual',source_id uuid,source_key text,cash_flow text NOT NULL DEFAULT 'operating' CHECK(cash_flow IN ('operating','investing','financing','transfer','opening')),reversal_of uuid,created_by uuid NOT NULL,posted_by uuid,posted_at timestamptz,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),UNIQUE(company_id,code),UNIQUE(company_id,source_key),UNIQUE(company_id,reversal_of),FOREIGN KEY(company_id,reversal_of) REFERENCES tenant.fin_journals(company_id,id),FOREIGN KEY(company_id,created_by) REFERENCES tenant.users(company_id,id),FOREIGN KEY(company_id,posted_by) REFERENCES tenant.users(company_id,id));
CREATE TABLE tenant.fin_journal_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,journal_id uuid NOT NULL,account_id uuid NOT NULL,party_id uuid,branch_id uuid,cost_centre_id uuid,project_id uuid,team_id uuid,memo text NOT NULL DEFAULT '',debit_minor bigint NOT NULL DEFAULT 0,credit_minor bigint NOT NULL DEFAULT 0,CHECK(debit_minor BETWEEN 0 AND 999999999999999999 AND credit_minor BETWEEN 0 AND 999999999999999999 AND ((debit_minor>0 AND credit_minor=0) OR (credit_minor>0 AND debit_minor=0))),FOREIGN KEY(company_id,journal_id) REFERENCES tenant.fin_journals(company_id,id),FOREIGN KEY(company_id,account_id) REFERENCES tenant.fin_accounts(company_id,id),FOREIGN KEY(company_id,party_id) REFERENCES tenant.fin_parties(company_id,id),FOREIGN KEY(company_id,branch_id) REFERENCES tenant.fin_dimensions(company_id,id),FOREIGN KEY(company_id,cost_centre_id) REFERENCES tenant.fin_dimensions(company_id,id),FOREIGN KEY(company_id,project_id) REFERENCES tenant.fin_dimensions(company_id,id),FOREIGN KEY(company_id,team_id) REFERENCES tenant.fin_dimensions(company_id,id));
CREATE INDEX fin_lines_account ON tenant.fin_journal_lines(company_id,account_id,journal_id);
CREATE INDEX fin_lines_party ON tenant.fin_journal_lines(company_id,party_id,journal_id);
CREATE INDEX fin_journal_date ON tenant.fin_journals(company_id,entry_date,status);
CREATE TABLE tenant.fin_treasuries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('cash','bank')),account_id uuid NOT NULL,bank_reference text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,UNIQUE(company_id,id),UNIQUE(company_id,account_id),UNIQUE(company_id,name),FOREIGN KEY(company_id,account_id) REFERENCES tenant.fin_accounts(company_id,id));
CREATE TABLE tenant.fin_agreements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,developer_id uuid NOT NULL,name text NOT NULL,mode text NOT NULL CHECK(mode IN ('percent','fixed','tiers')),rate_bps integer NOT NULL DEFAULT 0 CHECK(rate_bps BETWEEN 0 AND 10000),fixed_minor bigint NOT NULL DEFAULT 0 CHECK(fixed_minor>=0),tiers jsonb NOT NULL DEFAULT '[]',agent_bps integer NOT NULL DEFAULT 0,lead_bps integer NOT NULL DEFAULT 0,due_days integer NOT NULL DEFAULT 30 CHECK(due_days BETWEEN 0 AND 730),active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,UNIQUE(company_id,id),FOREIGN KEY(company_id,developer_id) REFERENCES tenant.fin_parties(company_id,id),CHECK(agent_bps>=0 AND lead_bps>=0 AND agent_bps+lead_bps<=10000));
CREATE TABLE tenant.fin_deals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,contract_id uuid NOT NULL,snapshot jsonb NOT NULL,contract_version integer NOT NULL,state text NOT NULL DEFAULT 'needs_review' CHECK(state IN ('needs_review','booked','needs_adjustment','cancelled')),agreement_id uuid,booked_version integer,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),UNIQUE(company_id,contract_id),FOREIGN KEY(company_id,contract_id) REFERENCES tenant.contracts(company_id,id),FOREIGN KEY(company_id,agreement_id) REFERENCES tenant.fin_agreements(company_id,id));
CREATE TABLE tenant.fin_obligations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,code text NOT NULL,kind text NOT NULL CHECK(kind IN ('developer_claim','supplier_bill','expense','commission_payable','customer_funds','credit_note')),party_id uuid NOT NULL,developer_id uuid,contract_id uuid,deal_id uuid,entry_date date NOT NULL,due_date date NOT NULL,description text NOT NULL,net_minor bigint NOT NULL CHECK(net_minor>0),tax_bps integer NOT NULL DEFAULT 0 CHECK(tax_bps BETWEEN 0 AND 10000),tax_minor bigint NOT NULL DEFAULT 0 CHECK(tax_minor>=0),total_minor bigint NOT NULL CHECK(total_minor>0),account_id uuid,branch_id uuid,cost_centre_id uuid,project_id uuid,team_id uuid,collection_owner text NOT NULL DEFAULT 'company' CHECK(collection_owner IN ('company','developer')),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','approved','posted','rejected','cancelled')),review_note text NOT NULL DEFAULT '',created_by uuid NOT NULL,approved_by uuid,journal_id uuid,credit_for uuid,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),UNIQUE(company_id,code),FOREIGN KEY(company_id,party_id) REFERENCES tenant.fin_parties(company_id,id),FOREIGN KEY(company_id,developer_id) REFERENCES tenant.fin_parties(company_id,id),FOREIGN KEY(company_id,account_id) REFERENCES tenant.fin_accounts(company_id,id),FOREIGN KEY(company_id,journal_id) REFERENCES tenant.fin_journals(company_id,id),FOREIGN KEY(company_id,deal_id) REFERENCES tenant.fin_deals(company_id,id),FOREIGN KEY(company_id,contract_id) REFERENCES tenant.contracts(company_id,id),FOREIGN KEY(company_id,credit_for) REFERENCES tenant.fin_obligations(company_id,id),FOREIGN KEY(company_id,created_by) REFERENCES tenant.users(company_id,id),FOREIGN KEY(company_id,approved_by) REFERENCES tenant.users(company_id,id));
CREATE TABLE tenant.fin_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,code text NOT NULL,kind text NOT NULL CHECK(kind IN ('receipt','payment','transfer')),entry_date date NOT NULL,treasury_id uuid NOT NULL,to_treasury_id uuid,party_id uuid,counter_account_id uuid,amount_minor bigint NOT NULL CHECK(amount_minor>0),method text NOT NULL DEFAULT 'cash' CHECK(method IN ('cash','bank_transfer','card','cheque')),reference text NOT NULL DEFAULT '',memo text NOT NULL,obligation_id uuid,journal_id uuid NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),UNIQUE(company_id,code),FOREIGN KEY(company_id,treasury_id) REFERENCES tenant.fin_treasuries(company_id,id),FOREIGN KEY(company_id,to_treasury_id) REFERENCES tenant.fin_treasuries(company_id,id),FOREIGN KEY(company_id,party_id) REFERENCES tenant.fin_parties(company_id,id),FOREIGN KEY(company_id,counter_account_id) REFERENCES tenant.fin_accounts(company_id,id),FOREIGN KEY(company_id,obligation_id) REFERENCES tenant.fin_obligations(company_id,id),FOREIGN KEY(company_id,journal_id) REFERENCES tenant.fin_journals(company_id,id),FOREIGN KEY(company_id,created_by) REFERENCES tenant.users(company_id,id));
CREATE TABLE tenant.fin_cheques(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,number text NOT NULL,bank text NOT NULL,kind text NOT NULL CHECK(kind IN ('incoming','outgoing')),treasury_id uuid NOT NULL,party_id uuid NOT NULL,counter_account_id uuid,obligation_id uuid,amount_minor bigint NOT NULL CHECK(amount_minor>0),due_date date NOT NULL,status text NOT NULL DEFAULT 'held' CHECK(status IN ('held','deposited','cleared','bounced','cancelled','deferred')),transaction_id uuid,notes text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1,UNIQUE(company_id,id),UNIQUE(company_id,bank,number,kind),FOREIGN KEY(company_id,treasury_id) REFERENCES tenant.fin_treasuries(company_id,id),FOREIGN KEY(company_id,party_id) REFERENCES tenant.fin_parties(company_id,id),FOREIGN KEY(company_id,counter_account_id) REFERENCES tenant.fin_accounts(company_id,id),FOREIGN KEY(company_id,obligation_id) REFERENCES tenant.fin_obligations(company_id,id),FOREIGN KEY(company_id,transaction_id) REFERENCES tenant.fin_transactions(company_id,id));
CREATE TABLE tenant.fin_custodies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,code text NOT NULL,employee_id uuid NOT NULL,party_id uuid NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),purpose text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','active','closed','cancelled')),review_note text NOT NULL DEFAULT '',transaction_id uuid,version integer NOT NULL DEFAULT 1,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),UNIQUE(company_id,code),FOREIGN KEY(company_id,employee_id) REFERENCES tenant.hr_employees(company_id,id),FOREIGN KEY(company_id,party_id) REFERENCES tenant.fin_parties(company_id,id),FOREIGN KEY(company_id,transaction_id) REFERENCES tenant.fin_transactions(company_id,id),FOREIGN KEY(company_id,created_by) REFERENCES tenant.users(company_id,id));
CREATE TABLE tenant.fin_custody_settlements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,custody_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('expense','return')),amount_minor bigint NOT NULL CHECK(amount_minor>0),journal_id uuid NOT NULL,memo text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,custody_id) REFERENCES tenant.fin_custodies(company_id,id),FOREIGN KEY(company_id,journal_id) REFERENCES tenant.fin_journals(company_id,id),FOREIGN KEY(company_id,created_by) REFERENCES tenant.users(company_id,id));
CREATE TABLE tenant.fin_reconciliations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,treasury_id uuid NOT NULL,statement_date date NOT NULL,statement_minor bigint NOT NULL,book_minor bigint NOT NULL,difference_minor bigint NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','completed')),notes text NOT NULL DEFAULT '',created_by uuid NOT NULL,version integer NOT NULL DEFAULT 1,UNIQUE(company_id,id),UNIQUE(company_id,treasury_id,statement_date),FOREIGN KEY(company_id,treasury_id) REFERENCES tenant.fin_treasuries(company_id,id),FOREIGN KEY(company_id,created_by) REFERENCES tenant.users(company_id,id));
CREATE TABLE tenant.fin_reconciled_lines(company_id uuid NOT NULL,reconciliation_id uuid NOT NULL,line_id uuid NOT NULL,PRIMARY KEY(company_id,line_id),FOREIGN KEY(company_id,reconciliation_id) REFERENCES tenant.fin_reconciliations(company_id,id),FOREIGN KEY(line_id) REFERENCES tenant.fin_journal_lines(id));
CREATE TABLE tenant.fin_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES platform.companies(id),entity_kind text NOT NULL,entity_id uuid NOT NULL,name text NOT NULL,mime text NOT NULL,size integer NOT NULL CHECK(size BETWEEN 1 AND 5242880),sha256 text NOT NULL,content bytea NOT NULL,uploaded_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,id),FOREIGN KEY(company_id,uploaded_by) REFERENCES tenant.users(company_id,id));
CREATE TABLE tenant.fin_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES platform.companies(id),entity_id uuid NOT NULL,kind text NOT NULL,actor_id uuid NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(company_id,actor_id) REFERENCES tenant.users(company_id,id));
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['fin_settings','fin_counters','fin_accounts','fin_dimensions','fin_parties','fin_periods','fin_journals','fin_journal_lines','fin_treasuries','fin_agreements','fin_deals','fin_obligations','fin_transactions','fin_cheques','fin_custodies','fin_custody_settlements','fin_reconciliations','fin_reconciled_lines','fin_attachments','fin_events'] LOOP
 EXECUTE format('ALTER TABLE tenant.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE tenant.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_isolation ON tenant.%I USING(company_id=nullif(current_setting(''app.company_id'',true),'''')::uuid) WITH CHECK(company_id=nullif(current_setting(''app.company_id'',true),'''')::uuid)',t);
 EXECUTE format('GRANT SELECT,INSERT ON tenant.%I TO mujez_tenant',t);
 END LOOP;
END $$;
GRANT UPDATE ON tenant.fin_settings,tenant.fin_counters,tenant.fin_accounts,tenant.fin_dimensions,tenant.fin_parties,tenant.fin_periods,tenant.fin_journals,tenant.fin_treasuries,tenant.fin_agreements,tenant.fin_deals,tenant.fin_obligations,tenant.fin_cheques,tenant.fin_custodies,tenant.fin_reconciliations TO mujez_tenant;
GRANT DELETE,UPDATE ON tenant.fin_journal_lines TO mujez_tenant;
CREATE FUNCTION tenant.fin_guard_journal() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE d numeric;c numeric;n integer;
BEGIN
 IF TG_OP='UPDATE' AND OLD.status='posted' THEN RAISE EXCEPTION 'Posted journals are immutable; create a reversal' USING ERRCODE='23514'; END IF;
 IF NEW.status='posted' THEN
  SELECT count(*),coalesce(sum(debit_minor),0),coalesce(sum(credit_minor),0) INTO n,d,c FROM tenant.fin_journal_lines WHERE company_id=NEW.company_id AND journal_id=NEW.id;
  IF n<2 OR d=0 OR d<>c THEN RAISE EXCEPTION 'Journal must have balanced debit and credit lines' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM tenant.fin_periods WHERE company_id=NEW.company_id AND NOT closed AND NEW.entry_date BETWEEN start_date AND end_date) THEN RAISE EXCEPTION 'An open financial period is required' USING ERRCODE='23514'; END IF;
 END IF;RETURN NEW;
END $$;
CREATE TRIGGER fin_journal_guard BEFORE INSERT OR UPDATE ON tenant.fin_journals FOR EACH ROW EXECUTE FUNCTION tenant.fin_guard_journal();
CREATE FUNCTION tenant.fin_guard_line() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF TG_OP<>'INSERT' AND EXISTS(SELECT 1 FROM tenant.fin_journals WHERE company_id=OLD.company_id AND id=OLD.journal_id AND status='posted') THEN RAISE EXCEPTION 'Posted journal lines are immutable' USING ERRCODE='23514';END IF;
 IF TG_OP<>'DELETE' AND EXISTS(SELECT 1 FROM tenant.fin_journals WHERE company_id=NEW.company_id AND id=NEW.journal_id AND status='posted') THEN RAISE EXCEPTION 'Posted journal lines are immutable' USING ERRCODE='23514';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $$;
CREATE TRIGGER fin_line_guard BEFORE INSERT OR UPDATE OR DELETE ON tenant.fin_journal_lines FOR EACH ROW EXECUTE FUNCTION tenant.fin_guard_line();
CREATE FUNCTION tenant.fin_capture_contract() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
BEGIN
 IF NEW.seed_key IS NOT NULL OR NEW.status NOT IN ('signed','void') THEN RETURN NEW;END IF;
 INSERT INTO tenant.fin_deals(company_id,contract_id,contract_version,snapshot,state) VALUES(NEW.company_id,NEW.id,NEW.version,jsonb_build_object('reference',NEW.public_id,'type',NEW.type,'valueMinor',NEW.value_minor::text,'leadId',NEW.lead_id,'ownerId',NEW.owner_id,'unitId',NEW.unit_id,'status',NEW.status,'signedDate',NEW.signed_date),CASE WHEN NEW.status='void' THEN 'cancelled' ELSE 'needs_review' END)
 ON CONFLICT(company_id,contract_id) DO UPDATE SET contract_version=excluded.contract_version,snapshot=excluded.snapshot,state=CASE WHEN tenant.fin_deals.booked_version IS NOT NULL AND tenant.fin_deals.booked_version<>excluded.contract_version THEN 'needs_adjustment' WHEN tenant.fin_deals.booked_version IS NOT NULL THEN tenant.fin_deals.state ELSE excluded.state END,version=tenant.fin_deals.version+1,updated_at=now();
 RETURN NEW;
END $$;
CREATE TRIGGER fin_contract_capture AFTER INSERT OR UPDATE OF status,value_minor,version ON tenant.contracts FOR EACH ROW EXECUTE FUNCTION tenant.fin_capture_contract();
-- Existing contracts enter the review inbox, not the ledger.
INSERT INTO tenant.fin_deals(company_id,contract_id,contract_version,snapshot,state) SELECT company_id,id,version,jsonb_build_object('reference',public_id,'type',type,'valueMinor',value_minor::text,'leadId',lead_id,'ownerId',owner_id,'unitId',unit_id,'status',status,'signedDate',signed_date),'needs_review' FROM tenant.contracts WHERE status='signed' AND seed_key IS NULL;

ALTER TABLE tenant.fin_journal_lines ADD UNIQUE(company_id,id);
ALTER TABLE tenant.fin_reconciled_lines DROP CONSTRAINT fin_reconciled_lines_line_id_fkey;
ALTER TABLE tenant.fin_reconciled_lines ADD FOREIGN KEY(company_id,line_id) REFERENCES tenant.fin_journal_lines(company_id,id);
CREATE FUNCTION tenant.fin_owner_permissions() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NEW.key='company_owner' AND 'workspace.view'=ANY(NEW.permissions) THEN NEW.permissions:=NEW.permissions||ARRAY(SELECT permission FROM unnest(ARRAY['finance.read','finance.write','finance.post','finance.approve','finance.settings']) WITH ORDINALITY x(permission,n) WHERE NOT(permission=ANY(NEW.permissions)) ORDER BY n);END IF;RETURN NEW;END $$;
CREATE TRIGGER fin_owner_permissions BEFORE INSERT OR UPDATE ON tenant.roles FOR EACH ROW EXECUTE FUNCTION tenant.fin_owner_permissions();
UPDATE tenant.roles SET permissions=permissions WHERE key='company_owner';
INSERT INTO tenant.roles(company_id,key,name,permissions,scope)
 SELECT c.id,r.key,r.name,r.permissions,'own' FROM platform.companies c CROSS JOIN (VALUES
 ('accountant','{"en":"Accountant","ar":"محاسب"}'::jsonb,ARRAY['finance.read','finance.write','finance.post']::text[]),
 ('finance_manager','{"en":"Finance Manager","ar":"مدير مالي"}'::jsonb,ARRAY['finance.read','finance.write','finance.post','finance.approve','finance.settings']::text[])
 ) r(key,name,permissions) ON CONFLICT(company_id,key) DO NOTHING;
CREATE OR REPLACE FUNCTION platform.provision_company_employee_roles(p_company uuid,p_name text,p_email text,p_roles text[],p_actor uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_primary text;v_role uuid;v_user uuid;v_account uuid;
BEGIN
 IF p_roles IS NULL OR cardinality(p_roles)<1 OR cardinality(p_roles)>8 OR array_position(p_roles,NULL) IS NOT NULL OR NOT (p_roles <@ ARRAY['agent','team_lead','employee','hr_officer','hr_manager','payroll_officer','accountant','finance_manager']::text[]) OR cardinality(p_roles)<>(SELECT count(DISTINCT x) FROM unnest(p_roles)x) THEN RAISE EXCEPTION 'Unsupported company roles' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform.companies WHERE id=p_company AND status IN ('pending','trial','active')) THEN RAISE EXCEPTION 'Company unavailable'; END IF;
 IF NOT EXISTS(SELECT 1 FROM tenant.users u JOIN tenant.roles r ON r.company_id=u.company_id AND r.id=u.role_id WHERE u.company_id=p_company AND u.id=p_actor AND u.identity_pool='company_admin' AND u.status='active' AND u.deleted_at IS NULL AND r.key='company_owner') THEN RAISE EXCEPTION 'Company owner required' USING ERRCODE='42501'; END IF;
 v_primary:=CASE WHEN 'team_lead'=ANY(p_roles) THEN 'team_lead' WHEN 'agent'=ANY(p_roles) THEN 'agent' WHEN 'finance_manager'=ANY(p_roles) THEN 'finance_manager' WHEN 'accountant'=ANY(p_roles) THEN 'accountant' WHEN 'hr_manager'=ANY(p_roles) THEN 'hr_manager' WHEN 'hr_officer'=ANY(p_roles) THEN 'hr_officer' WHEN 'payroll_officer'=ANY(p_roles) THEN 'payroll_officer' ELSE 'employee' END;
 INSERT INTO tenant.roles(company_id,key,name,permissions,scope)
 SELECT p_company,r.key,r.name,r.permissions,'own' FROM (VALUES
 ('accountant','{"en":"Accountant","ar":"محاسب"}'::jsonb,ARRAY['finance.read','finance.write','finance.post']::text[]),
 ('finance_manager','{"en":"Finance Manager","ar":"مدير مالي"}'::jsonb,ARRAY['finance.read','finance.write','finance.post','finance.approve','finance.settings']::text[]),
 ('employee','{"en":"Employee","ar":"موظف"}'::jsonb,ARRAY['leave.self']::text[]),
 ('hr_officer','{"en":"HR Officer","ar":"مسؤول الموارد البشرية"}'::jsonb,ARRAY['hr.read','hr.manage','leave.manage']::text[]),
 ('hr_manager','{"en":"HR Manager","ar":"مدير الموارد البشرية"}'::jsonb,ARRAY['hr.read','hr.manage','leave.manage','leave.approve']::text[]),
 ('payroll_officer','{"en":"Payroll Officer","ar":"مسؤول الرواتب"}'::jsonb,ARRAY[]::text[])
 ) r(key,name,permissions) ON CONFLICT(company_id,key) DO NOTHING;
 IF v_primary IN ('agent','team_lead') THEN
  v_account:=platform.provision_company_employee(p_company,p_name,p_email,v_primary);
  SELECT user_id INTO v_user FROM platform.company_employee_accounts WHERE id=v_account;
 ELSE
  INSERT INTO tenant.roles(company_id,key,name,permissions,scope) VALUES(p_company,'employee','{"en":"Employee","ar":"موظف"}',ARRAY['leave.self']::text[],'own') ON CONFLICT(company_id,key) DO NOTHING;
  SELECT id INTO v_role FROM tenant.roles WHERE company_id=p_company AND key=v_primary;
  INSERT INTO tenant.users(company_id,oidc_subject,identity_pool,name,email,role_id,status) VALUES(p_company,'password-employee:'||gen_random_uuid()::text,'company_user',p_name,p_email,v_role,'invited') RETURNING id INTO v_user;
  INSERT INTO platform.company_employee_accounts(company_id,user_id,name,email) VALUES(p_company,v_user,p_name,p_email) RETURNING id INTO v_account;
 END IF;
 INSERT INTO tenant.roles(company_id,key,name,permissions,scope) VALUES(p_company,'employee','{"en":"Employee","ar":"موظف"}',ARRAY['leave.self']::text[],'own') ON CONFLICT(company_id,key) DO NOTHING;
 IF 'agent'=ANY(p_roles) THEN
  INSERT INTO tenant.roles(company_id,key,name,permissions,scope) VALUES(p_company,'agent','{"en":"Sales Agent","ar":"وكيل المبيعات"}',ARRAY['leads.read','leads.manage','pipeline.read','pipeline.manage','contacts.read','contacts.manage','calendar.read','calendar.manage','tasks.read','tasks.manage','projects.read','units.read','reservations.read','reservations.manage','contracts.read','contracts.manage','commissions.read','documents.read','documents.manage'],'own') ON CONFLICT(company_id,key) DO NOTHING;
 END IF;
 INSERT INTO tenant.user_additional_roles(company_id,user_id,role_id) SELECT p_company,v_user,id FROM tenant.roles WHERE company_id=p_company AND key=ANY(p_roles) AND key<>v_primary;
 INSERT INTO tenant.audit_logs(company_id,actor_user_id,action,resource_type,resource_id,after) VALUES(p_company,p_actor,'employee.invited','user',v_user,jsonb_build_object('roles',p_roles));
 RETURN v_account;
END $$;
ALTER TABLE tenant.fin_obligations ADD COLUMN settlement_minor bigint CHECK(settlement_minor>=0);
