DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['fin_source_links','fin_offsets'] LOOP EXECUTE format('ALTER TABLE tenant.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE tenant.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_isolation ON tenant.%I USING(company_id=nullif(current_setting(''app.company_id'',true),'''')::uuid) WITH CHECK(company_id=nullif(current_setting(''app.company_id'',true),'''')::uuid)',t);EXECUTE format('GRANT SELECT,INSERT ON tenant.%I TO mujez_tenant',t);END LOOP;END $$;
